import {
  PreMediaCanplayMessage,
  PreMediaEndedMessage,
  PreMediaErrorMessage,
  PreMediaMessageTypes,
} from '@content/scripts/media/preMedia/types';

export const isPreMediaEndedMessage = (
  data: PreMediaEndedMessage,
): data is PreMediaEndedMessage => {
  return data && data.type === PreMediaMessageTypes.PRE_MEDIA_ENDED;
};

export const isPreMediaErrorMessage = (
  data: PreMediaErrorMessage,
): data is PreMediaErrorMessage => {
  return data && data.type === PreMediaMessageTypes.PRE_MEDIA_ERROR;
};

export const isPreMediaCanplayMessage = (
  data: PreMediaCanplayMessage,
): data is PreMediaCanplayMessage => {
  return data && data.type === PreMediaMessageTypes.PRE_MEDIA_CANPLAY;
};
