import {
  MOVIE_PLAYER_ID,
  BLOCKER_WARNING_OVERLAY_ID,
} from '@content/scripts/media/shared/constants';
import { PRE_MEDIA_OVERLAY_ID } from '@content/scripts/media/preMedia/constants';
import { Actions } from '@app/actions/shared';
import {
  getLocalStorageData,
  setLocalStorageData,
} from '@app/storage/local/shared';
import { LocalStorageKey } from '@app/storage/local/types/sharedTypes';
import { Events } from '@app/events';
import {
  isPreMediaCanplayMessage,
  isPreMediaEndedMessage,
  isPreMediaErrorMessage,
} from '@content/scripts/media/preMedia/utils';
import {
  TurnOffConflictingExtensionMessage,
  isMessageOfType,
} from '@app/messages/shared';
import { Feature } from '@app/features/types/Feature';
import { browser_api } from '@app/browser_api';
import { getRegionKey } from '@content/i18n/utils';
import i18n from '@content/i18n';
import { detectBrowser } from '@app/utils/detectBrowser';
import { messageDispatcher } from '@app/infrastructure/messageDispatcher';
import {
  isYTMethodResultMessage,
  pauseYouTubePlayer,
  playYouTubePlayer,
} from '../shared/utils';
import { shouldShowMedia } from '@content/utils/shouldShowMedia';
import { logger } from '@utils/logger';

const PRE_MEDIA_CANPLAY_TIMEOUT_MS = 3000;
let preMediaCanplayTimeoutId: ReturnType<typeof setTimeout> | null = null;
let isPreMediaCanplayReceived = false;

const formatMultiline = (text: string) => text.replace(/\n/g, '<br/>');

const clearPreMediaCanplayTimeout = () => {
  if (preMediaCanplayTimeoutId) {
    clearTimeout(preMediaCanplayTimeoutId);
    preMediaCanplayTimeoutId = null;
  }
};

const closeOverlayHandler = async (overlay: HTMLElement) => {
  if (!overlay.isConnected) return;
  overlay.remove();
  await setLocalStorageData({
    [LocalStorageKey.LastPreMediaClosed]: Date.now(),
  });
  playYouTubePlayer();
};

const createBlockerWarningContent = (
  overlay: HTMLElement,
  conflictingExtensionName?: string,
  extensionId?: string,
) => {
  const container = document.createElement('div');
  container.style.cssText = `
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    padding: 24px;
    text-align: center;
    color: #fff;
    font-size: 16px;
    line-height: 1.4;
    max-width: 360px;
  `;

  const emojiElement = document.createElement('div');
  emojiElement.textContent = '😔';
  emojiElement.style.cssText = `
    font-size: 72px;
    line-height: 1;
  `;

  const conflictingExtensionDisplayName =
    conflictingExtensionName ??
    i18n.t('content:preMedia.blockerWarning.unknownExtension');

  const extensionDisplayName = i18n.t(
    `content:extensionTitle.${process.env.EXTENSION_CODE}`,
  );

  const nameElement = document.createElement('div');
  nameElement.innerHTML = formatMultiline(
    i18n.t('content:preMedia.blockerWarning.useExtension', {
      conflictingExtensionDisplayName,
      extensionDisplayName,
    }),
  );
  nameElement.style.cssText = `
    font-size: 20px;
    font-weight: 700;
  `;

  const browser = detectBrowser();
  const isFirefox = browser === 'firefox';
  const disableExtensionKey = `content:preMedia.blockerWarning.disableExtension.${isFirefox ? 'firefox' : 'chrome'}`;

  const textElement = document.createElement('p');
  textElement.innerHTML = formatMultiline(
    i18n.t(disableExtensionKey, {
      extensionDisplayName,
    }),
  );
  textElement.style.cssText = `
    margin: 0;
  `;

  const buttonElement = document.createElement('button');
  const buttonTextKey = `content:preMedia.blockerWarning.buttonText.${isFirefox ? 'firefox' : 'chrome'}`;
  buttonElement.textContent = i18n.t(buttonTextKey);
  buttonElement.style.cssText = `
    margin-top: 8px;
    padding: 12px 24px;
    background: #ff4d4f;
    color: #fff;
    border: none;
    border-radius: 999px;
    font-size: 16px;
    font-weight: 600;
    cursor: ${extensionId ? 'pointer' : 'not-allowed'};
    opacity: ${extensionId ? '1' : '0.6'};
  `;
  buttonElement.disabled = !extensionId;

  const chromeOnClickHandler = () => {
    if (!extensionId) return;
    void messageDispatcher.send({
      action: Actions.DisableConflictingExtension,
      payload: { extensionId },
    });
  };
  const firefoxOnClickHandler = async () => {
    if (!extensionId) return;
    const link = 'about:addons';
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(link);
        return true;
      }
    } catch (e) {}

    try {
      const textarea = document.createElement('textarea');
      textarea.value = link;
      textarea.style.position = 'fixed';
      textarea.style.opacity = '0';
      document.body.appendChild(textarea);
      textarea.focus();
      textarea.select();

      const success = document.execCommand('copy');
      document.body.removeChild(textarea);
      return success;
    } catch {
      return false;
    }
  };

  buttonElement.addEventListener(
    'click',
    isFirefox ? firefoxOnClickHandler : chromeOnClickHandler,
  );

  buttonElement.addEventListener('mouseenter', () => {
    buttonElement.style.opacity = '0.7';
  });

  buttonElement.addEventListener('mouseleave', () => {
    buttonElement.style.opacity = '1';
  });

  const closeButton = document.createElement('button');

  const line1 = document.createElement('span');
  const line2 = document.createElement('span');

  [line1, line2].forEach((line) => {
    line.style.cssText = `
    position: absolute;
    top:0;
    left: 15px;
    width: 2px;
    height: 33px;
    background-color: #fff;
  `;
  });

  line1.style.transform = 'rotate(45deg)';
  line2.style.transform = 'rotate(-45deg)';

  closeButton.style.cssText = `
  background: none;
  border: none;
  padding: 0;
  margin: 0;

  box-sizing: border-box;
  position: absolute;
  top: 20px;
  right: 20px;
  width: 32px;
  height: 32px;

  cursor: pointer;
`;

  closeButton.addEventListener('click', () => {
    browser_api.runtime.sendMessage<TurnOffConflictingExtensionMessage>({
      action: Actions.TurnOffConflictingExtensionWarning,
    });
    closeOverlayHandler(overlay);
  });

  closeButton.addEventListener('mouseenter', () => {
    closeButton.style.opacity = '0.7';
  });

  closeButton.addEventListener('mouseleave', () => {
    closeButton.style.opacity = '1';
  });

  closeButton.append(line1, line2);

  container.append(
    emojiElement,
    nameElement,
    textElement,
    buttonElement,
    closeButton,
  );
  return container;
};

const onMessageListener = async (event: MessageEvent) => {
  const data = event.data;

  if (isYTMethodResultMessage(data)) {
    return;
  }

  const overlay = document.getElementById(PRE_MEDIA_OVERLAY_ID);

  if (!overlay) {
    return;
  }

  if (isPreMediaCanplayMessage(data)) {
    isPreMediaCanplayReceived = true;
    clearPreMediaCanplayTimeout();
    await setLocalStorageData({
      [LocalStorageKey.IsPreMediaCurrentlyShown]: true,
    });
    return;
  }

  if (isPreMediaEndedMessage(data)) {
    clearPreMediaCanplayTimeout();
    await setLocalStorageData({
      [LocalStorageKey.IsPreMediaCurrentlyShown]: false,
    });
    await closeOverlayHandler(overlay);
    window.removeEventListener('message', onMessageListener);
    return;
  }

  if (isPreMediaErrorMessage(data)) {
    clearPreMediaCanplayTimeout();
    logger.error('[beforeStartMedia] No URL found.', data.error);
    await setLocalStorageData({
      [LocalStorageKey.IsPreMediaCurrentlyShown]: false,
    });
    await closeOverlayHandler(overlay);
    window.removeEventListener('message', onMessageListener);
    return;
  }
};

const addListeners = () => {
  window.addEventListener('message', onMessageListener);
};

const removePreMedia = () => {
  window.removeEventListener('message', onMessageListener);
  clearPreMediaCanplayTimeout();
  isPreMediaCanplayReceived = false;

  const overlay = document.getElementById(PRE_MEDIA_OVERLAY_ID);
  if (overlay) {
    overlay.remove();
  }
};

const injectPreMedia = async (preMediaUrl: string) => {
  const player = document.getElementById(MOVIE_PLAYER_ID);
  if (!player) return;
  pauseYouTubePlayer();
  if (document.getElementById(PRE_MEDIA_OVERLAY_ID)) return;
  isPreMediaCanplayReceived = false;
  const overlay = document.createElement('div');
  overlay.id = PRE_MEDIA_OVERLAY_ID;
  overlay.style.cssText = `
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: black;
    z-index: 9999;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
  `;

  const iframe = document.createElement('iframe');
  iframe.src = preMediaUrl;
  iframe.style.cssText = `
    width: 100%;
    height: 100%;
    object-fit: contain;
  `;

  addListeners();
  overlay.appendChild(iframe);
  player.appendChild(overlay);

  clearPreMediaCanplayTimeout();
  preMediaCanplayTimeoutId = setTimeout(async () => {
    if (isPreMediaCanplayReceived) {
      return;
    }

    logger.warn(
      '[beforeStartMedia] PRE_MEDIA_CANPLAY timeout reached, removing preMedia overlay',
    );

    await setLocalStorageData({
      [LocalStorageKey.IsPreMediaCurrentlyShown]: false,
    });
    window.removeEventListener('message', onMessageListener);
    clearPreMediaCanplayTimeout();
    isPreMediaCanplayReceived = false;
    overlay.remove();
    playYouTubePlayer();
  }, PRE_MEDIA_CANPLAY_TIMEOUT_MS);
};

const checkAndInjectBlockerWarning = async () => {
  const player = document.getElementById(MOVIE_PLAYER_ID);
  if (!player) return false;

  const existingOverlay = document.getElementById(BLOCKER_WARNING_OVERLAY_ID);

  const { extensionMonitoring } = await getLocalStorageData(
    LocalStorageKey.ExtensionMonitoring,
  );

  const adBlockerMonitoring = extensionMonitoring?.adBlocker;

  if (!adBlockerMonitoring?.hasConflictingExtension) {
    if (existingOverlay) {
      existingOverlay.remove();
      playYouTubePlayer();
    }
    await setLocalStorageData({
      [LocalStorageKey.IsPreMediaCurrentlyShown]: false,
    });
    return false;
  }

  pauseYouTubePlayer();

  if (existingOverlay) {
    return true;
  }

  const { conflictingExtensionName, conflictingExtensionId } =
    adBlockerMonitoring;

  const overlay = document.createElement('div');
  overlay.id = BLOCKER_WARNING_OVERLAY_ID;
  overlay.style.cssText = `
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    background: #000;
    opacity: 0.95;
    z-index: 10000;
    display: flex;
    align-items: center;
    justify-content: center;
  `;

  overlay.appendChild(
    createBlockerWarningContent(
      overlay,
      conflictingExtensionName,
      conflictingExtensionId,
    ),
  );
  player.appendChild(overlay);

  return true;
};

async function checkPreMedia() {
  try {
    if (location.pathname !== '/watch') {
      removePreMedia();
      return;
    }
    const urlParams = new URLSearchParams(location.search);
    if (!urlParams.has('v')) return;

    const {
      lastPreMediaClosed,
      hasPremium,
      metaApiData,
      featureStoreV2,
      isExtensionConflictWarningAdBlockerAlarmExisted,
      currentLocale,
    } = await getLocalStorageData([
      LocalStorageKey.LastPreMediaClosed,
      LocalStorageKey.HasPremium,
      LocalStorageKey.MetaApiData,
      LocalStorageKey.FeatureStoreV2,
      LocalStorageKey.IsExtensionConflictWarningAdBlockerAlarmExisted,
      LocalStorageKey.CurrentLocale,
    ]);

    if (
      hasPremium ||
      isExtensionConflictWarningAdBlockerAlarmExisted ||
      currentLocale !== 'ru'
    )
      return;

    const isBlockerWarningVisible = await checkAndInjectBlockerWarning();

    if (isBlockerWarningVisible) return;

    const {
      beforeStartMediaUrls,
      mediaMaxVersionChrome,
      mediaMaxVersionFirefox,
      beforeStartMediaIntervalInMinutes,
    } = metaApiData ?? {};
    const isFirefox = detectBrowser() === 'firefox';

    const key = await getRegionKey();
    const preMediaUrl = beforeStartMediaUrls?.[key];

    const featuresList = {
      ...featureStoreV2?.featuresList,
      ...featureStoreV2?.featuresListLocal,
    };
    const isVideoPreMediaEnabled = Boolean(
      featuresList?.[Feature.BeforeStartMedia],
    );

    if (!isVideoPreMediaEnabled) return;

    if (!preMediaUrl) {
      logger.error('[beforeStartMedia] No URL found.');
      return;
    }

    if (!beforeStartMediaIntervalInMinutes) {
      logger.error(
        '[beforeStartMedia] beforeStartMediaIntervalInMinutes are missing',
      );
      return;
    }

    if (isFirefox && !mediaMaxVersionFirefox) {
      logger.error('[beforeStartMedia] mediaMaxVersionFirefox are missing');
      return;
    }

    if (!isFirefox && !mediaMaxVersionChrome) {
      logger.error('[beforeStartMedia] mediaMaxVersionChrome are missing');
      return;
    }

    const currentVersion = browser_api.runtime.getManifest().version;

    const shouldShow = shouldShowMedia(
      currentVersion,
      isFirefox,
      mediaMaxVersionChrome,
      mediaMaxVersionFirefox,
    );

    if (!shouldShow) {
      logger.error(
        isFirefox
          ? '[beforeStartMedia] mediaMaxVersionFirefox is lower than current version'
          : '[beforeStartMedia] mediaMaxVersionChrome is lower than current version',
      );
      return;
    }

    const now = Date.now();

    if (
      !lastPreMediaClosed ||
      now - lastPreMediaClosed >= beforeStartMediaIntervalInMinutes * 60 * 1000
    ) {
      void injectPreMedia(preMediaUrl);
    }
  } catch (e) {
    logger.error('[beforeStartMedia] error:', e);
  }
}

const extensionMonitoringUpdatedListener = (message: unknown) => {
  if (!isMessageOfType(message, Actions.ExtensionMonitoringUpdated)) {
    return;
  }

  void checkPreMedia();
};

if (
  !browser_api.runtime.onMessage.hasListener(extensionMonitoringUpdatedListener)
) {
  browser_api.runtime.onMessage.addListener(extensionMonitoringUpdatedListener);
}

void checkPreMedia();
window.addEventListener(Events.ytPlayerUpdated, checkPreMedia);

window.addEventListener(Events.YtNavigateFinish, checkPreMedia);

window.addEventListener('popstate', checkPreMedia);
