export enum PreMediaMessageTypes {
  PRE_MEDIA_ENDED = 'PRE_MEDIA_ENDED',
  PRE_MEDIA_ERROR = 'PRE_MEDIA_ERROR',
  PRE_MEDIA_CANPLAY = 'PRE_MEDIA_CANPLAY',
}

export interface PreMediaEndedMessage {
  type: PreMediaMessageTypes.PRE_MEDIA_ENDED;
}

export interface PreMediaErrorMessage {
  type: PreMediaMessageTypes.PRE_MEDIA_ERROR;
  error: unknown;
}

export interface PreMediaCanplayMessage {
  type: PreMediaMessageTypes.PRE_MEDIA_CANPLAY;
}
