export enum YTMessageTypes {
  YT_METHOD_CALL = 'YT_METHOD_CALL',
  YT_METHOD_RESULT = 'YT_METHOD_RESULT',
}

export enum YTPlayerState {
  UNSTARTED = -1,
  ENDED = 0,
  PLAYING = 1,
  PAUSED = 2,
  BUFFERING = 3,
  CUED = 5,
}

export interface YTbPlayer {
  pauseVideo(): void;

  playVideo(): void;

  getPlayerState(): number;
}

export interface YTMethodCallMessage {
  source: string;
  type: YTMessageTypes.YT_METHOD_CALL;
  method: keyof YTbPlayer;
}

export interface YTMethodResultMessage {
  source: string;
  type: YTMessageTypes.YT_METHOD_RESULT;
  method?: keyof YTbPlayer;
  result: any;
}
